#ifndef JJFFE_CONTOUR_TESSELLATE_H
#define JJFFE_CONTOUR_TESSELLATE_H

#include "jjffe/vertex_transform.h"
#include <vector>

namespace jjffe {

// A single 3D point generated by the contour tessellator (16.16 world).
struct ContourPoint3D {
    int32_t x = 0;
    int32_t y = 0;
    int32_t z = 0;
};

// Continuous flattened Contour boundary (ring). isHole set after Clipper2.
struct ContourRing {
    std::vector<ContourPoint3D> points;
    bool isHole = false;
};

// Phase 1: extract 3D polyline rings from a Contour group (shared contourId).
// Phase 2+: Clipper2 + earcut live in BuildContourWorldFaces.
class ContourTessellator {
public:
    // Digon pairs / mixed bezier+bridge edge-walk → closed rings (not raw soup).
    // Empty result → BuildContourWorldFaces falls back to TessellateEvenOddEdges.
    static std::vector<ContourRing> ExtractRings(const TransformedPoly* const* pieces,
                                                 int nPieces);

    // 3D adaptation of C721SpanAddBezier: >>16 subdivision heuristic, int64 DDA.
    static void EvaluateBezier3D(const ContourPoint3D& p0, const ContourPoint3D& p1,
                                 const ContourPoint3D& p2, const ContourPoint3D& p3,
                                 ContourRing& outRing);
};

// Tessellate Complex721 Contour groups into ContourHull triangles for GPU.
// Skips FUNC_001736 / 0x20ee glints (remain ScreenHybrid).
// Soft C721SpanFlush is unchanged — call this only from HW paths.
// Kill-switch: JJFFE_CONTOUR_3D=0 returns 0.
int BuildContourWorldFaces(const TransformedPoly* polys, int polyCount,
                           const ShipModel* model, const int32_t* shipRotFp16,
                           WorldFace* outFaces, int maxFaces);

bool Contour3dEnabled();

// Planar even-odd row tiles (O1). Default on for the D3D dig path / ctest.
// Exporters turn this off — those tiles are the Blender sails.
void SetContourRowTilesEnabled(bool enabled);
bool ContourRowTilesEnabled();

inline bool IsContourGlintPoly(const TransformedPoly& p)
{
    return p.texInfo == 0x20ee && (p.specialParam & 0xFFF0) == 0x7360;
}

} // namespace jjffe

#endif
